import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

function registerCounting(registry: ToolRegistry, name: string, inputSchema: ToolDefinition['inputSchema']) {
  const calls: Array<Record<string, unknown>> = [];
  registry.register({name, description: `Test tool ${name}`, inputSchema}, async input => {
    calls.push(input);
    return 'ok';
  });
  return calls;
}

describe('ToolRegistry.execute input validation', () => {
  it('returns location as required and skips the executor for empty input', async () => {
    const registry = new ToolRegistry();
    const calls = registerCounting(registry, 'get_weather', {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    });

    const response = await registry.execute('get_weather', {});

    expect({calls, result: response.result}).toEqual({
      calls: [],
      result: 'Invalid input for get_weather: location is required',
    });
  });

  it('names the nested field path and expected type but not the value for a wrong-typed property', async () => {
    const registry = new ToolRegistry();
    const calls = registerCounting(registry, 'get_forecast', {
      type: 'object',
      properties: {range: {type: 'object', properties: {days: {type: 'integer'}}}},
    });

    const response = await registry.execute('get_forecast', {range: {days: 'seventeen'}});

    expect({calls, result: response.result}).toEqual({
      calls: [],
      result: 'Invalid input for get_forecast: range.days must be integer',
    });
  });
});

describe('ToolRegistry.register schema compilation', () => {
  it('throws naming broken_weather for an unknown JSON Schema type', () => {
    const registry = new ToolRegistry();

    expect(() => registerCounting(registry, 'broken_weather', {type: 'object', properties: {x: {type: 'nope'}}})).toThrow(
      'Invalid inputSchema for tool broken_weather'
    );
  });
});

