import {ToolRegistry} from './registry.js';

describe('ToolRegistry.execute input validation', () => {
  it('returns location as required and skips the executor for empty input', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: 'Invalid input for get_weather: location is required',
    });
  });
});

describe('ToolRegistry.register schema compilation', () => {
  it('throws naming broken_weather for an unknown JSON Schema type', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow('Invalid inputSchema for tool broken_weather');
  });
});

